namespace ghidra.program.database.symbol;

using db;
using ghidra.program.model.address;
using ghidra.program.model.symbol;
using ghidra.util.Lock;

/**
 * Symbol class for namespaces.
 */
public class NamespaceSymbol : SymbolDB {

	private NamespaceDB @namespace;

	/**
	 * Construct a new namespace symbol
	 * @param mgr the symbol manager.
	 * @param record the record for this symbol.
	 */
	NamespaceSymbol(SymbolManager mgr, DBRecord record) : base(mgr, Address.NO_ADDRESS, record, record.getKey())
    {
	}

	/* @Override */
	public bool isPrimary() {
		return true;
	}

	/* @Override */
	public bool isExternal() {
		Symbol parentSymbol = getParentSymbol();
		return parentSymbol != null ? parentSymbol.isExternal() : false;
	}

	/* @Override */
	public SymbolType getSymbolType() {
		return SymbolType.NAMESPACE;
	}

	/* @Override */
	public Namespace getObject() {
		using (Closeable c = @lock.read())
{
			if (!refreshIfNeeded()) {
				return null;
			}
			if (@namespace == null) {
				@namespace = new NamespaceDB(this, symbolMgr.getProgram().getNamespaceManager());
			}
			return @namespace;
		}
	}

	/* @Override */
	public bool isValidParent(Namespace parent) {
		// TODO: Not sure what other constraints should be placed on namespace movement
		return base.isValidParent(parent) && SymbolType.NAMESPACE
				.isValidParent(symbolMgr.getProgram(), parent, address, isExternal());
	}
}
